import java.io.*;
import java.util.*;

public class Main {
    static final int MAXN = 66;
    static int r, c, n;
    static String s;
    static long[][] comb = new long[MAXN][MAXN];
    static long[] cnt_a = new long[MAXN];
    static long[] cnt_b = new long[MAXN];
    static ArrayList<Long>[] partial = new ArrayList[MAXN];
    static ArrayList<Long>[] partial_zero = new ArrayList[MAXN];

    static class Pair {
        long first, second;
        Pair(long f, long s) { first = f; second = s; }
    }

    static void compute_comb() {
        for (int i = 0; i <= n; ++i) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; ++j)
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
        }
    }

    static long get_difs(long conf, int a_bef, int b_bef) {
        long ans = 0;
        for (int i = 0; i < c + 1; ++i) {
            if ((conf & (1L << i)) != 0) {
                ++b_bef;
                long aux1 = comb[b_bef - 1][r - 1];
                long aux2 = comb[n - b_bef][r] - comb[a_bef][r];
                ans -= aux1 * aux2;
            } else {
                ++a_bef;
                long aux1 = comb[a_bef - 1][r - 1];
                long aux2 = comb[n - a_bef][r] - comb[b_bef][r];
                ans += aux1 * aux2;
            }
        }
        return ans;
    }

    static boolean check(long conf) {
        for (int i = 0; i < c + 1; ++i) {
            if (s.charAt(2 * r + c + i) == 'A' && ((conf >> i) & 1) == 1) return false;
            if (s.charAt(2 * r + c + i) == 'B' && ((conf >> i) & 1) == 0) return false;
        }
        return true;
    }

    static void compute_second_part() {
        long limit = 1L << (c + 1);
        for (long conf = 0; conf < limit; ++conf) {
            int b_here = Long.bitCount(conf);
            int a_here = c + 1 - b_here;
            long val = get_difs(conf, r + c - a_here, r + c - b_here);
            if (check(conf))
                partial[a_here].add(val);
            else
                partial_zero[a_here].add(val);
        }
        for (int i = 0; i <= c + 1; ++i) {
            Collections.sort(partial[i]);
            Collections.sort(partial_zero[i]);
        }
    }

    static long get_coef(long conf) {
        int i, j;
        for (i = 0; i < c + 1; ++i)
            if (((conf >> i) & 1) != (conf & 1))
                break;
        for (j = i; j < c + 1; ++j) {
            if (s.charAt(2 * r - 1 + j) == 'A' && ((conf >> j) & 1) == 1) return 0;
            if (s.charAt(2 * r - 1 + j) == 'B' && ((conf >> j) & 1) == 0) return 0;
        }
        int set_a = r - 1 + ((conf & 1) == 0 ? i : 0);
        int set_b = r - 1 + ((conf & 1) == 1 ? i : 0);
        if (set_a < cnt_a[2 * r - 2 + i]) return 0;
        if (set_b < cnt_b[2 * r - 2 + i]) return 0;
        return comb[set_a + set_b - cnt_a[2 * r - 2 + i] - cnt_b[2 * r - 2 + i]][set_a - cnt_a[2 * r - 2 + i]];
    }

    static void upd(Pair ans, Pair act) {
        if (act.first < 0) act.first = -act.first;
        if (ans.first < act.first) return;
        if (ans.first > act.first) {
            ans.first = act.first;
            ans.second = act.second;
            return;
        }
        ans.second += act.second;
    }

    static long how_many(ArrayList<Long> data, long val) {
        int left = lowerBound(data, val);
        int right = upperBound(data, val);
        return right - left;
    }

    static int lowerBound(ArrayList<Long> list, long key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid) < key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(ArrayList<Long> list, long key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid) <= key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static long compute_first_part() {
        long limit = 1L << (c + 1);
        Pair ans = new Pair(1L << 60, 0);
        for (long conf = 0; conf < limit; ++conf) {
            int b_here = Long.bitCount(conf);
            int a_here = c + 1 - b_here;
            long act = get_difs(conf, r - 1, r - 1);
            long coef = get_coef(conf);
            int idx = lowerBound(partial[c + 1 - a_here], -act);
            if (idx < partial[c + 1 - a_here].size()) {
                long val = partial[c + 1 - a_here].get(idx);
                if (ans.first >= Math.abs(val + act)) {
                    long coef2 = how_many(partial[c + 1 - a_here], val);
                    upd(ans, new Pair(val + act, coef * coef2));
                }
            }
            if (idx > 0) {
                --idx;
                long val = partial[c + 1 - a_here].get(idx);
                if (ans.first >= Math.abs(val + act)) {
                    long coef2 = how_many(partial[c + 1 - a_here], val);
                    upd(ans, new Pair(val + act, coef * coef2));
                }
            }
            coef = 0;
            idx = lowerBound(partial_zero[c + 1 - a_here], -act);
            if (idx < partial_zero[c + 1 - a_here].size()) {
                long val = partial_zero[c + 1 - a_here].get(idx);
                if (ans.first >= Math.abs(val + act)) {
                    long coef2 = how_many(partial_zero[c + 1 - a_here], val);
                    upd(ans, new Pair(val + act, coef * coef2));
                }
            }
            if (idx > 0) {
                --idx;
                long val = partial_zero[c + 1 - a_here].get(idx);
                if (ans.first >= Math.abs(val + act)) {
                    long coef2 = how_many(partial_zero[c + 1 - a_here], val);
                    upd(ans, new Pair(val + act, coef * coef2));
                }
            }
        }
        return ans.second;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        r = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        s = br.readLine();
        s = " " + s; // make 1-indexed
        n = 2 * (r + c);
        for (int i = 0; i < MAXN; ++i) {
            partial[i] = new ArrayList<>();
            partial_zero[i] = new ArrayList<>();
        }
        compute_comb();
        for (int i = 1; i <= n; ++i) {
            cnt_a[i] = cnt_a[i - 1] + (s.charAt(i) == 'A' ? 1 : 0);
            cnt_b[i] = cnt_b[i - 1] + (s.charAt(i) == 'B' ? 1 : 0);
        }
        compute_second_part();
        long sol = compute_first_part();
        System.out.println(sol);
    }
}
